import { describe, it, expect, vi } from 'vitest';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

import { hashMessage } from '~/utils';
import { discordMessageShape } from '~/server/api/utils/shapes';
import { normalizeForHash } from '~/providers/MessageProvider/usePusher';

describe('hashMessage producer/consumer parity after normalizeForHash', () => {
  it('a trailing space in classic content does not create a false mismatch', () => {
    const saved = { content: 'hello world' };
    const draftWithSpace = { content: 'hello world ' };
    expect(hashMessage(normalizeForHash({ name: 'Test', updatedAt: 0, data: draftWithSpace } as never)))
      .toBe(hashMessage({ name: 'Test', data: discordMessageShape.parse(saved) }));
  });

  it('a trailing space in a V2 button label does not create a false mismatch', () => {
    const saved = {
      flags: 32768,
      components: [{ type: 1, components: [{
        type: 2, style: 5, label: 'Click me', url: 'https://example.com',
      }] }],
    };
    const draftWithSpace = {
      flags: 32768,
      components: [{ type: 1, components: [{
        type: 2, style: 5, label: 'Click me ', url: 'https://example.com',
      }] }],
    };
    expect(hashMessage(normalizeForHash({ name: 'Test', updatedAt: 0, data: draftWithSpace } as never)))
      .toBe(hashMessage({ name: 'Test', data: discordMessageShape.parse(saved) }));
  });

  it('a leading space in a V2 accessory (thumbnail) URL does not create a false mismatch', () => {
    const saved = {
      flags: 32768,
      components: [{
        type: 9,
        components: [{ type: 10, content: 'hi' }],
        accessory: { type: 11, media: { url: 'https://example.com/a.png' } },
      }],
    };
    const draftWithSpace = {
      flags: 32768,
      components: [{
        type: 9,
        components: [{ type: 10, content: 'hi' }],
        accessory: { type: 11, media: { url: ' https://example.com/a.png' } },
      }],
    };
    expect(hashMessage(normalizeForHash({ name: 'Test', updatedAt: 0, data: draftWithSpace } as never)))
      .toBe(hashMessage({ name: 'Test', data: discordMessageShape.parse(saved) }));
  });

  it('control: a genuine V2 component-body edit still mismatches (the whitespace fix is not undone)', () => {
    const saved = {
      flags: 32768,
      components: [{ type: 17, components: [{ type: 10, content: 'hi' }] }],
    };
    const changed = {
      flags: 32768,
      components: [{ type: 17, components: [{ type: 10, content: 'a totally different body' }] }],
    };
    expect(hashMessage(normalizeForHash({ name: 'Test', updatedAt: 0, data: changed } as never)))
      .not.toBe(hashMessage({ name: 'Test', data: discordMessageShape.parse(saved) }));
  });

  it('normalizeForHash still strips `_key`s and ORs the V2 flag from structure (stripKeys, unchanged)', () => {
    const draft = {
      components: [{ _key: 'a', type: 17, components: [{ _key: 'b', type: 10, content: 'hi' }] }],
    };
    const result = normalizeForHash({ name: 'Test', updatedAt: 0, data: draft } as never);
    expect(result.data.flags).toBe(32768);
    expect(JSON.stringify(result.data)).not.toContain('_key');
  });

  it('falls back to the stripKeys form (not a throw) when the live draft fails shape validation', () => {
    const invalidDraft = { content: 'hi', avatar_url: 'not-a-url' };
    expect(() => normalizeForHash({ name: 'Test', updatedAt: 0, data: invalidDraft } as never))
      .not.toThrow();
  });
});
